"""Frontier exploration with optional YOLO-World/MobileSAM object approach."""

import math
import time
from types import SimpleNamespace

import numpy as np
import rclpy
from geometry_msgs.msg import PoseStamped
from message_filters import ApproximateTimeSynchronizer, Subscriber
from nav2_msgs.action import NavigateToPose
from nav_msgs.msg import OccupancyGrid
from rclpy.action import ActionClient
from rclpy.duration import Duration
from rclpy.node import Node
from rclpy.qos import qos_profile_sensor_data
from rclpy.time import Time
from sensor_msgs.msg import CameraInfo, Image
from std_msgs.msg import String
from tf2_ros import Buffer, TransformException, TransformListener
from visualization_msgs.msg import Marker, MarkerArray

from .navigation_algorithms import grid_to_world, select_frontier, standoff_candidates, world_to_grid


SEARCHING = "SEARCHING"
TARGET_CONFIRMED = "TARGET_CONFIRMED"
APPROACHING = "APPROACHING"
SUCCEEDED = "SUCCEEDED"
FAILED = "FAILED"


def yaw_quaternion(yaw):
    return (0.0, 0.0, math.sin(yaw / 2.0), math.cos(yaw / 2.0))


def rotate_vector(q, vector):
    """Rotate a vector by geometry_msgs Quaternion without extra dependencies."""
    x, y, z, w = q.x, q.y, q.z, q.w
    matrix = np.array([
        [1 - 2 * (y*y + z*z), 2 * (x*y - z*w), 2 * (x*z + y*w)],
        [2 * (x*y + z*w), 1 - 2 * (x*x + z*z), 2 * (y*z - x*w)],
        [2 * (x*z - y*w), 2 * (y*z + x*w), 1 - 2 * (x*x + y*y)],
    ])
    return matrix @ np.asarray(vector, dtype=float)


class SemanticExplorer(Node):
    def __init__(self):
        super().__init__("semantic_explorer")
        defaults = {
            "map_topic": "/map", "global_frame": "map", "base_frame": "base_link",
            "navigate_action": "/navigate_to_pose", "target_object": "chair",
            "detection_confidence": 0.65, "confirm_frames": 3,
            "confirmation_radius": 0.35, "standoff_distance": 0.8,
            "exploration_timeout": 120.0, "goal_reached_distance": 0.35,
            "min_frontier_cells": 8, "frontier_replan_period": 3.0,
            "enable_perception": False, "rgb_topic": "/camera/color/image_raw",
            "depth_topic": "/camera/aligned_depth_to_color/image_raw",
            "camera_info_topic": "/camera/color/camera_info",
            "camera_frame": "camera_color_optical_frame", "min_valid_depth_pixels": 30,
            "max_detection_depth": 4.0, "model_device": "cuda:0",
        }
        for name, value in defaults.items():
            self.declare_parameter(name, value)
        self.p = SimpleNamespace(**{name: self.get_parameter(name).value for name in defaults})

        self.map_message = None
        self.grid = None
        self.state = SEARCHING
        self.state_pub = self.create_publisher(String, "~/state", 10)
        self.marker_pub = self.create_publisher(MarkerArray, "~/markers", 10)
        self.create_subscription(OccupancyGrid, self.p.map_topic, self.on_map, 1)
        self.tf_buffer = Buffer(cache_time=Duration(seconds=30.0))
        self.tf_listener = TransformListener(self.tf_buffer, self)
        self.navigator = ActionClient(self, NavigateToPose, self.p.navigate_action)

        self.goal_handle = None
        self.goal_pending = False
        self.goal_kind = None
        self.goal_started = 0.0
        self.goal_token = 0
        self.last_frontier_goal = None
        self.target_position = None
        self.target_seen_time = 0.0
        self.confirm_positions = []
        self.last_inference = 0.0
        self.camera_info = None
        self.detector = None

        if self.p.enable_perception:
            self.create_subscription(CameraInfo, self.p.camera_info_topic, self.on_camera_info, 10)
            self.rgb_sub = Subscriber(self, Image, self.p.rgb_topic, qos_profile=qos_profile_sensor_data)
            self.depth_sub = Subscriber(self, Image, self.p.depth_topic, qos_profile=qos_profile_sensor_data)
            self.sync = ApproximateTimeSynchronizer([self.rgb_sub, self.depth_sub], 10, 0.10)
            self.sync.registerCallback(self.on_rgbd)
        else:
            self.get_logger().warn("Perception disabled: running frontier exploration only.")

        self.timer = self.create_timer(float(self.p.frontier_replan_period), self.tick)
        self.publish_state()

    def publish_state(self):
        message = String()
        message.data = self.state
        self.state_pub.publish(message)

    def set_state(self, state):
        if state != self.state:
            self.state = state
            self.get_logger().info(f"State -> {state}")
            self.publish_state()

    def on_map(self, message):
        expected = message.info.width * message.info.height
        if len(message.data) != expected or expected == 0:
            self.get_logger().warn("Ignoring malformed or empty OccupancyGrid")
            return
        self.map_message = message
        self.grid = np.asarray(message.data, dtype=np.int16).reshape(message.info.height, message.info.width)

    def robot_xy(self):
        try:
            transform = self.tf_buffer.lookup_transform(
                self.p.global_frame, self.p.base_frame, Time(), timeout=Duration(seconds=0.2))
            return transform.transform.translation.x, transform.transform.translation.y
        except TransformException as error:
            self.get_logger().warn(f"Robot TF unavailable: {error}", throttle_duration_sec=5.0)
            return None

    def tick(self):
        if self.grid is None or self.map_message is None or self.state in (SUCCEEDED, FAILED):
            return
        robot = self.robot_xy()
        if robot is None:
            return
        if self.goal_handle is not None or self.goal_pending:
            if time.monotonic() - self.goal_started > float(self.p.exploration_timeout):
                self.get_logger().warn("Navigation goal timed out; cancelling it")
                self.cancel_goal()
            return

        if self.target_position is not None and self.state in (TARGET_CONFIRMED, APPROACHING):
            candidates = standoff_candidates(
                self.grid, self.target_position[:2], robot,
                (self.map_message.info.origin.position.x, self.map_message.info.origin.position.y),
                self.map_message.info.resolution,
                radii=(float(self.p.standoff_distance),
                       float(self.p.standoff_distance) + 0.2,
                       float(self.p.standoff_distance) + 0.4),
            )
            if candidates:
                x, y, yaw, _ = candidates[0]
                self.set_state(APPROACHING)
                self.send_goal(x, y, yaw, "approach")
            else:
                self.get_logger().warn("No collision-free standoff pose; resuming exploration")
                self.target_position = None
                self.confirm_positions.clear()
                self.set_state(SEARCHING)
            return

        cell = world_to_grid(
            robot[0], robot[1], self.map_message.info.origin.position.x,
            self.map_message.info.origin.position.y, self.map_message.info.resolution)
        selected, clusters = select_frontier(self.grid, cell, int(self.p.min_frontier_cells))
        self.publish_frontiers(clusters)
        if selected is None:
            self.get_logger().warn("No reachable frontier remains")
            self.set_state(FAILED)
            return
        x, y = grid_to_world(
            selected["goal"][0], selected["goal"][1],
            self.map_message.info.origin.position.x, self.map_message.info.origin.position.y,
            self.map_message.info.resolution)
        yaw = math.atan2(y - robot[1], x - robot[0])
        self.last_frontier_goal = (x, y)
        self.send_goal(x, y, yaw, "frontier")

    def send_goal(self, x, y, yaw, kind):
        if not self.navigator.wait_for_server(timeout_sec=0.5):
            self.get_logger().warn("NavigateToPose action server is not available")
            return
        goal = NavigateToPose.Goal()
        goal.pose = PoseStamped()
        goal.pose.header.frame_id = self.p.global_frame
        goal.pose.header.stamp = self.get_clock().now().to_msg()
        goal.pose.pose.position.x = float(x)
        goal.pose.pose.position.y = float(y)
        qx, qy, qz, qw = yaw_quaternion(yaw)
        goal.pose.pose.orientation.x, goal.pose.pose.orientation.y = qx, qy
        goal.pose.pose.orientation.z, goal.pose.pose.orientation.w = qz, qw
        self.goal_token += 1
        token = self.goal_token
        self.goal_kind = kind
        self.goal_started = time.monotonic()
        self.goal_pending = True
        future = self.navigator.send_goal_async(goal)
        future.add_done_callback(lambda done: self.on_goal_response(done, token, kind))
        self.get_logger().info(f"Sending {kind} goal: ({x:.2f}, {y:.2f})")

    def on_goal_response(self, future, token, kind):
        handle = future.result()
        if token != self.goal_token:
            # A detection or timeout invalidated this request while Nav2 was
            # deciding whether to accept it. Cancel an accepted stale goal.
            if handle.accepted:
                handle.cancel_goal_async()
            return
        self.goal_pending = False
        if not handle.accepted:
            self.get_logger().warn(f"{kind} goal rejected")
            self.goal_handle = None
            if kind == "approach":
                self.target_position = None
                self.set_state(SEARCHING)
            return
        self.goal_handle = handle
        result = handle.get_result_async()
        result.add_done_callback(lambda done: self.on_goal_result(done, token, kind))

    def on_goal_result(self, future, token, kind):
        if token != self.goal_token:
            return
        status = future.result().status
        self.goal_handle = None
        self.goal_pending = False
        self.goal_kind = None
        if kind == "approach" and status == 4:  # action_msgs/GoalStatus.STATUS_SUCCEEDED
            visible_recently = time.monotonic() - self.target_seen_time < 5.0
            robot = self.robot_xy()
            target_distance = (
                math.hypot(robot[0] - self.target_position[0], robot[1] - self.target_position[1])
                if robot is not None and self.target_position is not None else math.inf
            )
            max_distance = float(self.p.standoff_distance) + 0.4 + float(self.p.goal_reached_distance)
            if visible_recently and target_distance <= max_distance:
                self.set_state(SUCCEEDED)
                return
            self.get_logger().warn(
                f"Approach completed without final confirmation "
                f"(visible={visible_recently}, target_distance={target_distance:.2f} m)")
            self.target_position = None
        self.set_state(SEARCHING)

    def cancel_goal(self):
        self.goal_token += 1  # invalidate callbacks from the old goal
        if self.goal_handle is not None:
            self.goal_handle.cancel_goal_async()
        self.goal_handle = None
        self.goal_pending = False
        self.goal_kind = None

    def on_camera_info(self, message):
        self.camera_info = message

    def ensure_detector(self):
        if self.detector is not None:
            return True
        try:
            from ultralytics import SAM, YOLO
            self.yolo = YOLO("yolov8l-world.pt").to(self.p.model_device)
            self.yolo.set_classes([self.p.target_object])
            self.sam = SAM("mobile_sam.pt").to(self.p.model_device)
            self.detector = True
            return True
        except Exception as error:
            self.get_logger().error(f"Cannot initialize perception models: {error}")
            self.set_state(FAILED)
            return False

    @staticmethod
    def image_array(message):
        channels = 3
        row = np.frombuffer(message.data, dtype=np.uint8).reshape(message.height, message.step)
        image = row[:, :message.width * channels].reshape(message.height, message.width, channels)
        return image[:, :, ::-1] if message.encoding.lower() == "rgb8" else image

    @staticmethod
    def depth_metres(message):
        row_bytes = message.step
        if message.encoding == "32FC1":
            row = np.frombuffer(message.data, dtype=np.uint8).reshape(message.height, row_bytes)
            return row[:, :message.width * 4].copy().view(np.float32).reshape(message.height, message.width)
        row = np.frombuffer(message.data, dtype=np.uint8).reshape(message.height, row_bytes)
        return row[:, :message.width * 2].copy().view(np.uint16).reshape(message.height, message.width) / 1000.0

    def on_rgbd(self, rgb_message, depth_message):
        if self.camera_info is None or self.state in (SUCCEEDED, FAILED):
            return
        if time.monotonic() - self.last_inference < 0.8:
            return
        self.last_inference = time.monotonic()
        if not self.ensure_detector():
            return
        image = self.image_array(rgb_message)
        depth = self.depth_metres(depth_message)
        results = self.yolo.predict(image, conf=float(self.p.detection_confidence), verbose=False)
        if not len(results[0].boxes):
            self.confirm_positions.clear()
            return
        boxes = results[0].boxes.xyxy
        sam_result = self.sam.predict(image, bboxes=boxes, verbose=False)[0]
        if sam_result.masks is None:
            return
        masks = sam_result.masks.data.cpu().numpy()
        confidences = results[0].boxes.conf.cpu().numpy()
        best = int(np.argmax(confidences))
        mask = masks[best].astype(np.uint8)
        if mask.shape != depth.shape:
            import cv2
            mask = cv2.resize(mask, (depth.shape[1], depth.shape[0]), interpolation=cv2.INTER_NEAREST)
        valid = (mask > 0) & np.isfinite(depth) & (depth > 0.15) & (depth < float(self.p.max_detection_depth))
        if np.count_nonzero(valid) < int(self.p.min_valid_depth_pixels):
            return
        rows, cols = np.nonzero(valid)
        z_values = depth[valid]
        z = float(np.median(z_values))
        # Median pixels near the median depth reject background leaking through a mask.
        near = np.abs(z_values - z) < 0.15
        u, v = float(np.median(cols[near])), float(np.median(rows[near]))
        fx, fy = self.camera_info.k[0], self.camera_info.k[4]
        cx, cy = self.camera_info.k[2], self.camera_info.k[5]
        camera_point = ((u - cx) * z / fx, (v - cy) * z / fy, z)
        try:
            transform = self.tf_buffer.lookup_transform(
                self.p.global_frame, self.p.camera_frame, Time.from_msg(depth_message.header.stamp),
                timeout=Duration(seconds=0.2))
        except TransformException as error:
            self.get_logger().warn(f"Image-time camera TF unavailable: {error}", throttle_duration_sec=5.0)
            return
        point = rotate_vector(transform.transform.rotation, camera_point)
        point += np.array([
            transform.transform.translation.x, transform.transform.translation.y,
            transform.transform.translation.z])
        self.confirm_detection(tuple(point))

    def confirm_detection(self, point):
        if self.confirm_positions:
            center = np.mean(self.confirm_positions, axis=0)
            if np.linalg.norm(np.asarray(point[:2]) - center[:2]) > float(self.p.confirmation_radius):
                self.confirm_positions.clear()
        self.confirm_positions.append(point)
        self.confirm_positions = self.confirm_positions[-int(self.p.confirm_frames):]
        self.target_seen_time = time.monotonic()
        if len(self.confirm_positions) < int(self.p.confirm_frames):
            return
        center = np.median(np.asarray(self.confirm_positions), axis=0)
        self.target_position = tuple(float(value) for value in center)
        self.publish_target_marker()
        if self.state == SEARCHING:
            self.set_state(TARGET_CONFIRMED)
            self.cancel_goal()

    def publish_frontiers(self, clusters):
        markers = MarkerArray()
        clear = Marker()
        clear.action = Marker.DELETEALL
        markers.markers.append(clear)
        if self.map_message is None:
            self.marker_pub.publish(markers)
            return
        for index, cluster in enumerate(clusters):
            marker = Marker()
            marker.header.frame_id = self.p.global_frame
            marker.header.stamp = self.get_clock().now().to_msg()
            marker.ns, marker.id, marker.type, marker.action = "frontiers", index, Marker.SPHERE, Marker.ADD
            x, y = grid_to_world(cluster["goal"][0], cluster["goal"][1],
                                 self.map_message.info.origin.position.x,
                                 self.map_message.info.origin.position.y,
                                 self.map_message.info.resolution)
            marker.pose.position.x, marker.pose.position.y = x, y
            marker.pose.orientation.w = 1.0
            marker.scale.x = marker.scale.y = marker.scale.z = 0.18
            marker.color.b, marker.color.g, marker.color.a = 1.0, 0.5, 0.9
            markers.markers.append(marker)
        self.marker_pub.publish(markers)

    def publish_target_marker(self):
        marker = Marker()
        marker.header.frame_id = self.p.global_frame
        marker.header.stamp = self.get_clock().now().to_msg()
        marker.ns, marker.id, marker.type, marker.action = "target", 0, Marker.SPHERE, Marker.ADD
        marker.pose.position.x, marker.pose.position.y, marker.pose.position.z = self.target_position
        marker.pose.orientation.w = 1.0
        marker.scale.x = marker.scale.y = marker.scale.z = 0.30
        marker.color.r, marker.color.g, marker.color.a = 1.0, 0.2, 1.0
        self.marker_pub.publish(MarkerArray(markers=[marker]))


def main(args=None):
    rclpy.init(args=args)
    node = SemanticExplorer()
    try:
        rclpy.spin(node)
    except KeyboardInterrupt:
        pass
    finally:
        node.cancel_goal()
        node.destroy_node()
        rclpy.shutdown()
